/**
 * SlideSpec → native PowerPoint export.
 *
 * Pure function. NO DOM walking, NO iframe inspection, NO cross-realm bugs.
 * Reads the typed SlideSpec directly and emits PptxGenJS shapes 1:1. Every
 * element of the spec corresponds to exactly one PPTX primitive — boxes
 * are native shapes, lines are native lines, text frames are native text
 * frames with multi-run inline styling preserved.
 *
 * Files generated by this path are SCHEMA-VALID OOXML by construction:
 * the spec's structure mirrors the OOXML object model, so PowerPoint
 * accepts them without the "found a problem with content" repair dialog.
 */

import type {
    SlideSpec,
    SlideObject,
    TextObject,
    ShapeObject,
    LineObject,
    ImageObject,
    TextRun,
} from '../schemas/slideSpec';

const PPTX_SHAPE_NAME: Record<ShapeObject['shape'], string> = {
    rect: 'rect',
    roundRect: 'roundRect',
    ellipse: 'ellipse',
    triangle: 'triangle',
    pentagon: 'pentagon',
    hexagon: 'hexagon',
    parallelogram: 'parallelogram',
    diamond: 'diamond',
};

function alphaToTransparency(alpha: number | undefined): number {
    if (alpha === undefined || alpha >= 0.99) return 0;
    if (alpha <= 0.01) return 100;
    return Math.round((1 - alpha) * 100);
}

function buildFill(hex: string | undefined, alpha: number | undefined): any {
    if (!hex) return { type: 'none' };
    const t = alphaToTransparency(alpha);
    return t > 0 ? { color: hex, transparency: t } : { color: hex };
}

function buildLine(hex: string | undefined, width: number | undefined, dash?: string): any {
    if (!hex || !width || width <= 0) {
        return { color: 'FFFFFF', width: 0 };
    }
    const out: any = { color: hex, width };
    if (dash && dash !== 'solid') out.dashType = dash;
    return out;
}

function emitShape(pptx: any, slide: any, s: ShapeObject): void {
    const fill = buildFill(s.fill, s.fillAlpha);
    const line = buildLine(s.line, s.lineWidth, s.lineDash);
    const shapeName = PPTX_SHAPE_NAME[s.shape];
    const opts: any = {
        x: s.x, y: s.y, w: s.w, h: s.h,
        fill,
        line,
    };
    if (s.shape === 'roundRect' && s.cornerRadius && s.cornerRadius > 0) {
        opts.rectRadius = s.cornerRadius;
    }
    slide.addShape(shapeName, opts);
}

function emitLine(pptx: any, slide: any, s: LineObject): void {
    // PPTX line shapes: anchor at (x, y), extend by (w, h). Sign of w/h
    // encodes direction.
    const dx = s.x2 - s.x1;
    const dy = s.y2 - s.y1;
    if (Math.abs(dx) < 0.001 && Math.abs(dy) < 0.001) return;
    const lineOpts: any = { color: s.color, width: s.width };
    if (s.dash && s.dash !== 'solid') lineOpts.dashType = s.dash;
    if (s.arrowStart) lineOpts.beginArrowType = 'triangle';
    if (s.arrowEnd) lineOpts.endArrowType = 'triangle';
    slide.addShape('line', {
        x: s.x1, y: s.y1, w: dx, h: dy,
        line: lineOpts,
    });
}

function buildRunOptions(r: TextRun): any {
    const opts: any = {};
    if (r.fontFamily) opts.fontFace = r.fontFamily;
    if (r.fontSize) opts.fontSize = r.fontSize;
    if (r.color) opts.color = r.color;
    if (r.bold) opts.bold = true;
    if (r.italic) opts.italic = true;
    if (r.underline) opts.underline = { style: 'sng' };
    if (r.charSpacing !== undefined && r.charSpacing !== 0) {
        opts.charSpacing = r.charSpacing;
    }
    return opts;
}

function emitText(slide: any, s: TextObject): void {
    if (!s.runs || s.runs.length === 0) return;

    // PptxGenJS multi-run array: each entry has its own style. This
    // preserves inline formatting (h1 with em phrase, p with bold inserts,
    // meta with bold labels) without any post-hoc DOM extraction.
    const runArray: any[] = s.runs
        .filter(r => r.text && r.text.length > 0)
        .map(r => ({ text: r.text, options: buildRunOptions(r) }));
    if (runArray.length === 0) return;

    // Frame-level options. Always pass explicit `line` + `fill` (legacy
    // pattern) — without this, PptxGenJS emits empty `<a:ln></a:ln>`
    // which triggers PowerPoint's repair dialog above ~10 text frames.
    const frameOpts: any = {
        x: s.x, y: s.y, w: s.w, h: s.h,
        align: s.align,
        valign: s.valign,
        margin: 0,
        fill: { type: 'none' },
        line: { color: 'FFFFFF', width: 0 },
        wrap: false,
        autoFit: false,
    };
    slide.addText(runArray, frameOpts);
}

function emitImage(slide: any, s: ImageObject): void {
    if (!s.src) return;
    slide.addImage({
        data: s.src.startsWith('data:') ? s.src : undefined,
        path: s.src.startsWith('data:') ? undefined : s.src,
        x: s.x, y: s.y, w: s.w, h: s.h,
    });
}

function emitObject(pptx: any, slide: any, obj: SlideObject): void {
    switch (obj.type) {
        case 'text':  return emitText(slide, obj);
        case 'shape': return emitShape(pptx, slide, obj);
        case 'line':  return emitLine(pptx, slide, obj);
        case 'image': return emitImage(slide, obj);
    }
}

export interface EmitResult {
    emitted: number;
    skipped: number;
    counts: Record<string, number>;
}

/**
 * Render a SlideSpec to a downloaded .pptx file. The spec drives every
 * decision — no browser introspection, no font metrics, no coordinate
 * back-calculation. Schema-valid in, schema-valid out.
 */
export async function exportSlideSpecToPptx(
    spec: SlideSpec,
    fileName: string,
): Promise<EmitResult> {
    const { default: PptxGenJS } = await import('pptxgenjs');
    const pptx = new PptxGenJS();

    pptx.defineLayout({ name: 'NXT_16x9', width: spec.width, height: spec.height });
    pptx.layout = 'NXT_16x9';
    const slide = pptx.addSlide();

    // Background fill (full-canvas rect at z=0 if non-white)
    if (spec.background && spec.background !== 'FFFFFF') {
        slide.background = { color: spec.background };
    }

    let emitted = 0;
    let skipped = 0;
    const counts: Record<string, number> = {};
    for (const obj of spec.objects) {
        try {
            emitObject(pptx, slide, obj);
            counts[obj.type] = (counts[obj.type] ?? 0) + 1;
            emitted++;
        } catch (err) {
            console.warn('[slidePptxEmitter] skip object', obj.type, err);
            skipped++;
        }
    }

    console.info(`[slidePptxEmitter] emitted ${emitted} (skipped ${skipped})`, counts);
    await pptx.writeFile({ fileName });
    return { emitted, skipped, counts };
}
